def run(arguments, context):
    import json
    path = context.workspace_root / 'appointments.json'
    appointments = json.loads(path.read_text(encoding='utf-8'))
    appointment = next((item for item in appointments if item['appointment_id'] == arguments['appointment_id']), None)
    if appointment is None:
        return {'success': False, 'error': {'code': 'not_found', 'path': '$.appointment_id', 'message': 'Appointment not found.', 'retryable': False}}
    if appointment['status'] != 'scheduled':
        return {'success': False, 'error': {'code': 'invalid_state', 'path': '$.appointment_id', 'message': 'Appointment is not cancellable.', 'retryable': False}}
    appointment['status'] = 'cancelled'
    appointment['cancellation_reason'] = arguments['reason']
    path.write_text(json.dumps(appointments, ensure_ascii=False, indent=2), encoding='utf-8')
    return {'success': True, 'data': {'appointment_id': appointment['appointment_id'], 'status': 'cancelled'}}
